<?php
require __DIR__ . '/bootstrap.php';
use Dilemma\{AiWaiting, Arguments, Connections, Db, Debates, ReadModel, Support, ToolRegistry};
$a=user_fixture('WaitA'); $b=user_fixture('WaitB'); $c=user_fixture('WaitC');
$d=debate_fixture($a['actor'],$b['actor'],false);$id=$d['id'];
$setup=Connections::current($b['actor'],$id);
preg_match('/Authorization: Bearer ([A-Za-z0-9_-]{43})/',$setup['setup_text'],$match);
$token=$match[1];$agent=Connections::authenticate('Bearer '.$token);
$check=static fn()=>ToolRegistry::invoke($agent,'dilemma_check_turn',(object)['debate_id'=>$id]);
check(!$setup['waiting']['enabled'] && !$check()['keep_waiting'],'Manual is the default, including existing participants');
check(str_contains($setup['setup_text'],'I chose manual mode') && !str_contains($setup['setup_text'],'Start a persistent goal'),'Copied setup never implicitly opts into waiting');
$start=time();$on=AiWaiting::update($b['actor'],['debate_id'=>$id,'enabled'=>true]);
check($on['waiting']['enabled'] && abs(strtotime($on['waiting']['until'])-$start-7200)<=2,'Explicit human choice starts exactly a two-hour window');
check($check()['keep_waiting'] && $check()['poll_after_seconds']===900,'Opted-in opposing side uses fifteen-minute checks');
check(strlen(Support::json($check()))<500 && !isset($check()['instructions']) && !isset($check()['messages']),'Idle check stays compact without full context or credentials');
check(str_contains($on['setup_text'],$on['waiting']['until']) && str_contains($on['setup_text'],'I selected optional automatic waiting'),'Copy includes the actual bounded opt-in');
$again=AiWaiting::update($b['actor'],['debate_id'=>$id,'enabled'=>true]);
check($again['waiting']['until']===$on['waiting']['until'],'Repeated enable cannot silently extend waiting');
rejects(fn()=>AiWaiting::update($agent,['debate_id'=>$id,'enabled'=>true]),403,'AI cannot grant or extend waiting');
rejects(fn()=>AiWaiting::update($c['actor'],['debate_id'=>$id,'enabled'=>true]),404,'Nonparticipant cannot start waiting');
rejects(fn()=>AiWaiting::update($b['actor'],['debate_id'=>$id,'enabled'=>'true']),422,'Invalid toggle is rejected');
check(!ReadModel::debate($id,$a['actor'])['workflow']['waiting']['enabled'],'One participant cannot opt in the other');
Db::run('UPDATE debate_participants SET ai_wait_until=? WHERE debate_id=? AND user_id=?',[gmdate('Y-m-d H:i:s',time()-1),$id,$b['actor']['user_id']]);
check(!$check()['keep_waiting'] && !$check()['waiting']['enabled'],'Expired window stops automatic waiting on the server');
check(Connections::authenticate('Bearer '.$token)['connection_id']===$agent['connection_id'],'Waiting expiry leaves persistent access valid');
AiWaiting::update($b['actor'],['debate_id'=>$id,'enabled'=>true]);
$off=AiWaiting::update($b['actor'],['debate_id'=>$id,'enabled'=>false]);
check(!$check()['keep_waiting'] && !$off['waiting']['enabled'] && str_contains($off['setup_text'],'I chose manual mode'),'Stop immediately changes server policy and setup');
Arguments::submit($a['actor'],$id,['revision'=>(int)Debates::row($id)['revision'],'idempotency_key'=>Support::token(),'body'=>'Opening case for the shared question.']);
check($check()['can_publish'] && !$check()['waiting']['enabled'],'Manual continuation can publish without re-enabling waiting');
$r=Arguments::submit($agent,$id,['revision'=>(int)Debates::row($id)['revision'],'idempotency_key'=>Support::token(),'body'=>'Full manual response after the waiting window ended.']);
check(isset($r['message_id']),'Persistent MCP grant still publishes after waiting is disabled');
$other=debate_fixture($a['actor'],$b['actor'],false);
rejects(fn()=>AiWaiting::status($agent,$other['id']),403,'Compact tool retains per-debate access scope');
AiWaiting::update($b['actor'],['debate_id'=>$id,'enabled'=>true]);
Connections::revoke($b['actor'],$agent['connection_id']);
check(Debates::member($id,$b['actor']['user_id'])['ai_wait_until']===null,'Revocation clears waiting too');
rejects(fn()=>Connections::authenticate('Bearer '.$token),401,'Revoked token cannot check or post');
echo 'SUCCESS: '.$checks." optional waiting checks.\n";
